/**
 * Salesforce Attachment Settings JavaScript
 * Handles UI interactions for attachment sync configuration
 */

(function($) {
    'use strict';

    const cinSFAttachmentSettings = window.cinSFAttachmentSettings || {};

    $(function() {
        // Initialize attachment settings
        initAttachmentSettings();
    });

    function initAttachmentSettings() {
        const $attachmentToggle = $('#attachment-sync-enable');
        const $attachmentOptions = $('.sf-attachment-field');

        if ($attachmentToggle.length) {
            // Toggle visibility of attachment options based on checkbox
            toggleAttachmentOptions();

            $attachmentToggle.on('change', function() {
                toggleAttachmentOptions();
            });
        }
    }

    function toggleAttachmentOptions() {
        const $attachmentToggle = $('#attachment-sync-enable');
        const $sizeInput = $('#max-attachment-size');
        const $visibilitySelect = $('#attachment-visibility');

        if ($attachmentToggle.is(':checked')) {
            $sizeInput.removeAttr('disabled');
            $visibilitySelect.removeAttr('disabled');
        } else {
            $sizeInput.attr('disabled', 'disabled');
            $visibilitySelect.attr('disabled', 'disabled');
        }
    }

    // Expose to window for inline use
    window.cinSFAttachmentSettings = cinSFAttachmentSettings;

})(jQuery);
